<?php
declare(strict_types=1);
require_once __DIR__ . '/../bootstrap/app.php';require_role('ADMIN');$rows=db_all("SELECT UserAccountID,Email,Role,Status,EmailVerifiedAt,LastLoginAt,CreatedAt FROM USER_ACCOUNT WHERE Role IN ('ADMIN','RECEPTIONIST') ORDER BY Role,Email");$pageTitle='Staff';$pageSubtitle='Administrative and reception accounts';include V3_ROOT.'/includes/header.php';?>
<section aria-labelledby="staff-directory-title"><h2 class="sr-only" id="staff-directory-title">Staff directory</h2><div class="table-wrap"><table><caption class="sr-only">Administrative and reception staff directory</caption><thead><tr><th>Email</th><th>Role</th><th>Status</th><th>Verified</th><th>Last login</th><th>Created</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['Email'])?></td><td><?=e($row['Role'])?></td><td><?=e($row['Status'])?></td><td><?=e($row['EmailVerifiedAt']??'—')?></td><td><?=e($row['LastLoginAt']??'Never')?></td><td><?=e($row['CreatedAt'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">No staff accounts.</td></tr><?php endif;?></tbody></table></div></section><?php include V3_ROOT.'/includes/footer.php';?>
